var pp = pl.GetProjectPosition(XYZ.Zero);
var plines = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_SiteProperty).WhereElementIsNotElementType().ToElements();
var outList = new List<object>();
foreach (var e in plines) {
  var verts = new List<XYZ>();
  var deps = e.GetDependentElements(new ElementClassFilter(typeof(CurveElement)));
  foreach (var id in deps) { var ce = doc.GetElement(id) as CurveElement; if (ce == null) continue; var c = ce.GeometryCurve; foreach (var p in new[]{c.GetEndPoint(0), c.GetEndPoint(1)}) if (!verts.Any(v => v.DistanceTo(new XYZ(p.X,p.Y,0)) < 0.003)) verts.Add(new XYZ(p.X,p.Y,0)); }
  // match each target to nearest vertex (current shared)
  var matches = targets.Select((t,i) => {
    var best = verts.OrderBy(v => { var s = inv.OfPoint(v); return Math.Pow(s.X*0.3048 - t.X,2)+Math.Pow(s.Y*0.3048 - t.Y,2); }).FirstOrDefault();
    if (best == null) return null;
    var s2 = inv.OfPoint(best);
    return new { pt = "P0"+(i+1), intX_m = Math.Round(best.X*0.3048,4), intY_m = Math.Round(best.Y*0.3048,4), curE = Math.Round(s2.X*0.3048,3), curN = Math.Round(s2.Y*0.3048,3), dE_m = Math.Round(t.X - s2.X*0.3048,3), dN_m = Math.Round(t.Y - s2.Y*0.3048,3) };
  }).ToList();
  outList.Add(new { id = e.Id.IntegerValue, name = e.Name, vertexCount = verts.Count, matches });
